await using var tx = await db.Database.BeginTransactionAsync(IsolationLevel.Serializable);
var existing = await db.LockRecords.SingleOrDefaultAsync(l => l.Lockable == key);
if (existing is { Owner: var owner } && owner != sessionId)
    return Results.Conflict($"locked by {existing.Owner}");
db.LockRecords.Add(new LockRecord { Lockable = key, Owner = sessionId,
                                    AcquiredAt = DateTime.UtcNow });
await db.SaveChangesAsync();
await tx.CommitAsync();   // the lock record now outlives this transaction
